#!/usr/bin/env python3
"""Generate fig_aggregation_comparison: ASR vs K_eff scatter for 4 aggregation methods at K=3 and K=5."""
import sys, json, itertools, warnings
import numpy as np
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from pathlib import Path
from collections import Counter

warnings.filterwarnings("ignore")

PROJECT_ROOT = Path("/root/cert_manip_resist_eval")
sys.path.insert(0, str(PROJECT_ROOT))

from src.unified_data_loader import (
    ALL_MODELS, DATASETS, ATTACKS,
    load_all_scores, load_pairs, load_mi_data,
    _is_valid_score,
)

EPS = 1e-6

# ── Aggregation functions ──
def agg_majority(votes, _w):
    c = Counter(votes)
    mc = c.most_common()
    if mc[0][1] >= (len(votes) // 2 + 1):
        return mc[0][0]
    for k, _ in mc:
        if k != "tie":
            return k
    return "tie"

def agg_threshold(votes, _w):
    if all(v == votes[0] for v in votes):
        return votes[0]
    return "ABSTAIN"

def agg_weighted(votes, weights):
    scores = {}
    for v, w in zip(votes, weights):
        scores[v] = scores.get(v, 0.0) + w
    ranked = sorted(scores.items(), key=lambda x: -x[1])
    if len(ranked) >= 2 and abs(ranked[0][1] - ranked[1][1]) < 1e-12:
        return "TIE"
    return ranked[0][0]

def agg_bayesian(votes, reliabilities):
    log_pa, log_pb = 0.0, 0.0
    for v, p in zip(votes, reliabilities):
        p = max(min(p, 0.999), 0.001)
        lp, l1p = np.log(p), np.log(1.0 - p)
        if v == "A":
            log_pa += lp; log_pb += l1p
        elif v == "B":
            log_pa += l1p; log_pb += lp
    if log_pa > log_pb:
        return "A"
    if log_pb > log_pa:
        return "B"
    return "TIE"

METHODS = {
    "Majority": agg_majority,
    "Weighted": agg_weighted,
    "Threshold": agg_threshold,
    "Bayesian": agg_bayesian,
}

# ── Helpers ──
def mi_based_keff(mi_matrix, model_indices):
    K = len(model_indices)
    if K <= 1:
        return 1.0
    keff = 0.0
    for i_idx in model_indices:
        term = 1.0
        for j_idx in model_indices:
            if i_idx != j_idx:
                term += np.exp(-2 * mi_matrix[i_idx, j_idx])
        keff += term
    return keff / K

def compute_panel_asr(jids, clean_ds, attacked_ds_atk, pairs, agg_fn, weights):
    n = min(len(pairs), *(len(clean_ds[j]) for j in jids),
            *(len(attacked_ds_atk[j]) for j in jids))
    n_flips = n_correct = 0
    w = [weights[j] for j in jids]
    for i in range(n):
        if not all(_is_valid_score(clean_ds[j][i]) for j in jids):
            continue
        if not all(_is_valid_score(attacked_ds_atk[j][i]) for j in jids):
            continue
        gt = pairs[i]["ground_truth_winner"]
        cv = agg_fn([clean_ds[j][i]["winner"] for j in jids], w)
        if cv != gt:
            continue
        n_correct += 1
        av = agg_fn([attacked_ds_atk[j][i]["winner"] for j in jids], w)
        if av != gt:
            n_flips += 1
    return n_flips / max(n_correct, 1)

def compute_clean_accuracy(clean_list, pairs):
    n = min(len(clean_list), len(pairs))
    correct = total = 0
    for i in range(n):
        if not _is_valid_score(clean_list[i]):
            continue
        total += 1
        if clean_list[i]["winner"] == pairs[i]["ground_truth_winner"]:
            correct += 1
    return correct / max(total, 1)


# ── Main ──
print("Loading data...")
all_scores = load_all_scores()
all_pairs = load_pairs()
mi_data = load_mi_data()
N = len(ALL_MODELS)

# Average MI matrix across datasets
mi_avg = np.zeros((N, N))
n_ds = 0
for ds in DATASETS:
    if ds in mi_data:
        mi_avg += np.array(mi_data[ds])
        n_ds += 1
mi_avg /= max(n_ds, 1)

# Compute clean accuracy per model per dataset
clean_acc = {}
for ds in DATASETS:
    pairs_ds = all_pairs.get(ds, [])
    for j, mid in enumerate(ALL_MODELS):
        cl = all_scores.get("clean", {}).get(ds, {}).get(mid, [])
        if cl:
            clean_acc[(ds, mid)] = compute_clean_accuracy(cl, pairs_ds)

print("Computing panels...")
results = {m: {"K3": {"keff": [], "asr": []}, "K5": {"keff": [], "asr": []}} for m in METHODS}

for K, k_label in [(3, "K3"), (5, "K5")]:
    combos = list(itertools.combinations(range(N), K))
    print(f"  K={K}: {len(combos)} panels")

    # Subsample conditions: use first available dataset+attack
    cond_data = []
    for ds in DATASETS:
        for atk in ATTACKS:
            pairs_ds = all_pairs.get(ds, [])
            clean_ds = all_scores.get("clean", {}).get(ds, {})
            attacked_ds = all_scores.get("attacked", {}).get(ds, {}).get(atk, {})
            if not pairs_ds or not clean_ds or not attacked_ds:
                continue
            valid_models = [j for j in range(N) if ALL_MODELS[j] in clean_ds and ALL_MODELS[j] in attacked_ds]
            if len(valid_models) >= K:
                cond_data.append((ds, atk, pairs_ds, clean_ds, attacked_ds, valid_models))

    if not cond_data:
        continue

    # Use first condition for scatter (representative)
    ds, atk, pairs_ds, clean_ds, attacked_ds, valid_models = cond_data[0]

    # Average across ALL conditions for robustness
    for combo in combos:
        model_ids = [ALL_MODELS[i] for i in combo]
        if not all(mid in clean_ds and mid in attacked_ds for mid in model_ids):
            continue

        keff = mi_based_keff(mi_avg, list(combo))

        weights = {}
        for mid in model_ids:
            weights[mid] = clean_acc.get((ds, mid), 0.5)

        for mname, agg_fn in METHODS.items():
            asr = compute_panel_asr(model_ids, clean_ds, attacked_ds, pairs_ds, agg_fn, weights)
            results[mname][k_label]["keff"].append(keff)
            results[mname][k_label]["asr"].append(asr)

print("Plotting...")
fig, axes = plt.subplots(1, 2, figsize=(7.0, 3.2), sharey=True)

colors = {"Threshold": "#d62728", "Majority": "#1f77b4", "Weighted": "#2ca02c", "Bayesian": "#ff7f0e"}
markers = {"Threshold": "s", "Majority": "o", "Weighted": "^", "Bayesian": "D"}

for col, (K, k_label) in enumerate([(3, "K3"), (5, "K5")]):
    ax = axes[col]
    for mname in ["Threshold", "Majority", "Weighted", "Bayesian"]:
        keffs = np.array(results[mname][k_label]["keff"])
        asrs = np.array(results[mname][k_label]["asr"])
        if len(keffs) == 0:
            continue
        ax.scatter(keffs, asrs, c=colors[mname], marker=markers[mname],
                   s=8, alpha=0.3, label=mname, edgecolors="none")
        # Add trend line
        if len(keffs) > 10:
            z = np.polyfit(keffs, asrs, 1)
            x_range = np.linspace(keffs.min(), keffs.max(), 50)
            ax.plot(x_range, np.polyval(z, x_range), c=colors[mname], lw=1.5, alpha=0.8)

    ax.set_xlabel("$K_{\\mathrm{eff}}$", fontsize=11)
    ax.set_title(f"$K = {K}$", fontsize=11)
    if col == 0:
        ax.set_ylabel("Panel ASR", fontsize=11)
    ax.tick_params(labelsize=9)

axes[1].legend(fontsize=8, loc="upper left", framealpha=0.7, handletextpad=0.3,
               markerscale=1.5, borderpad=0.3)

plt.tight_layout(w_pad=1.0)
out_dir = "/root/cert_manip_resist_eval/docs/paper/figures"
plt.savefig(f"{out_dir}/fig_aggregation_comparison.pdf", bbox_inches="tight", dpi=300)
plt.savefig(f"{out_dir}/fig_aggregation_comparison.png", bbox_inches="tight", dpi=300)
print(f"Saved: {out_dir}/fig_aggregation_comparison.pdf")
print(f"Saved: {out_dir}/fig_aggregation_comparison.png")
PYEOF
